'use client'

import { motion } from 'framer-motion'
import { useCallback, useState } from "react"
import Particles from "react-tsparticles"
import { loadSlim } from "tsparticles-slim"
import { useTheme } from '../context/ThemeContext'
import { FaGithub, FaLinkedin, FaEnvelope, FaPhone } from 'react-icons/fa'
import emailjs from '@emailjs/browser'
import toast from 'react-hot-toast'

// Custom Card component instead of shadcn/ui Card
const CustomCard = ({ children, style, className = "" }) => (
  <div 
    className={`p-6 shadow-lg backdrop-blur-lg rounded-xl border transition-all duration-300 hover:shadow-xl ${className}`}
    style={style}
  >
    {children}
  </div>
)

const content = {
  EN: {
    title: "Get In Touch",
    subtitle: "Let's Connect",
    connectTitle: "Connect With Me",
    formLabels: {
      name: "Name",
      email: "Email",
      message: "Message",
      submit: "Send Message"
    },
    toasts: {
      success: "Message sent successfully! 🎉",
      error: "Oops! Something went wrong 🤔"
    }
  },
  AR: {
    title: "تواصل معي",
    subtitle: "دعنا نتواصل",
    connectTitle: "تواصل معي",
    formLabels: {
      name: "الاسم",
      email: "البريد الإلكتروني",
      message: "الرسالة",
      submit: "إرسال الرسالة"
    },
    toasts: {
      success: "تم إرسال الرسالة بنجاح! 🎉",
      error: "عذراً! حدث خطأ ما 🤔"
    }
  }
}

const InputField = ({ label, id, type = "text", value, onChange, theme, rows }) => (
  <div className="space-y-2">
    <label htmlFor={id} className="block font-medium" style={{ color: theme.text }}>
      {label}
    </label>
    {rows ? (
      <textarea
        id={id}
        rows={rows}
        className="w-full px-4 py-3 rounded-lg focus:outline-none focus:ring-2 transition-all duration-300"
        style={{
          backgroundColor: `${theme.primary}10`,
          color: theme.text,
          borderColor: theme.primary,
          borderWidth: '1px'
        }}
        value={value}
        onChange={onChange}
        required
      />
    ) : (
      <input
        type={type}
        id={id}
        className="w-full px-4 py-3 rounded-lg focus:outline-none focus:ring-2 transition-all duration-300"
        style={{
          backgroundColor: `${theme.primary}10`,
          color: theme.text,
          borderColor: theme.primary,
          borderWidth: '1px'
        }}
        value={value}
        onChange={onChange}
        required
      />
    )}
  </div>
)

export default function Contact() {
  const { isDark, theme, language } = useTheme()
  const [isLoading, setIsLoading] = useState(false)
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    message: ''
  })
  
  const currentContent = content[language]
  const isRTL = language === 'AR'

  const particlesInit = useCallback(async engine => {
    await loadSlim(engine)
  }, [])

  const handleSubmit = async (e) => {
    e.preventDefault()
    setIsLoading(true)
    
    try {
      await emailjs.send(
        'YOUR_SERVICE_ID',
        'YOUR_TEMPLATE_ID',
        {
          from_name: formData.name,
          from_email: formData.email,
          message: formData.message,
          to_email: 'sebasalamah00@gmail.com',
        },
        'YOUR_PUBLIC_KEY'
      )
  
      setFormData({ name: '', email: '', message: '' })
      toast.success(currentContent.toasts.success)
    } catch (error) {
      toast.error(currentContent.toasts.error)
    } finally {
      setIsLoading(false)
    }
  }

  const socialLinks = [
    {
      icon: FaGithub,
      href: "https://github.com/Seba-00",
      label: "GitHub",
      color: isDark ? "#6e5494" : "#24292e"
    },
    {
      icon: FaLinkedin,
      href: "https://linkedin.com/in/seba-salamah",
      label: "LinkedIn",
      color: "#0077b5"
    },
    {
      icon: FaEnvelope,
      href: "mailto:sebasalamah00@gmail.com",
      label: "sebasalamah00@gmail.com",
      color: theme.primary
    },
    {
      icon: FaPhone,
      href: "tel:+966555948067",
      label: "+966 555 948 067",
      color: theme.primary
    }
  ]

  return (
    <section id="contact" className={`min-h-screen flex items-center justify-center relative overflow-hidden py-20 ${isRTL ? 'rtl' : 'ltr'}`}>
      <Particles
        id="tsparticles-contact"
        init={particlesInit}
        options={{
          background: { color: { value: "transparent" } },
          fpsLimit: 120,
          interactivity: {
            events: {
              onHover: { enable: true, mode: "repulse" },
              onClick: { enable: true, mode: "push" },
            },
            modes: {
              repulse: { distance: 150, duration: 0.4 },
              push: { quantity: 4 },
            },
          },
          particles: {
            color: { value: theme.primary },
            links: {
              color: theme.primary,
              distance: 150,
              enable: true,
              opacity: 0.3,
              width: 1,
            },
            move: {
              direction: "none",
              enable: true,
              outModes: { default: "bounce" },
              random: false,
              speed: 1.5,
              straight: false,
            },
            number: {
              density: { enable: true, area: 1000 },
              value: 60,
            },
            opacity: {
              value: 0.3,
              animation: {
                enable: true,
                speed: 0.8,
                minimumValue: 0.1,
              },
            },
            shape: { type: "circle" },
            size: { value: { min: 1, max: 2 } },
          },
          detectRetina: true,
        }}
      />

      <div className="container mx-auto px-4 z-10">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
          className="text-center mb-16"
        >
          <h2 
            className="font-mono text-lg mb-4 tracking-wider"
            style={{ color: theme.primary }}
          >
            {currentContent.title}
          </h2>
          <h3 
            className="text-5xl font-bold bg-clip-text text-transparent bg-gradient-to-r"
            style={{ 
              backgroundImage: `linear-gradient(to right, ${theme.primary}, ${theme.textSecondary})`
            }}
          >
            {currentContent.subtitle}
          </h3>
        </motion.div>

        <div className="grid md:grid-cols-2 gap-12 max-w-6xl mx-auto">
          {/* Social Links */}
          <motion.div
            initial={{ x: isRTL ? 100 : -100, opacity: 0 }}
            whileInView={{ x: 0, opacity: 1 }}
            transition={{ duration: 0.8 }}
          >
            <CustomCard style={{
              backgroundColor: isDark ? 'rgba(10, 25, 47, 0.8)' : 'rgba(255, 255, 255, 0.8)',
              borderColor: theme.primary
            }}>
              <h4 
                className="text-2xl font-bold mb-8"
                style={{ color: theme.primary }}
              >
                {currentContent.connectTitle}
              </h4>
              
              <div className="space-y-6">
                {socialLinks.map((link, index) => (
                  <motion.a
                    key={link.label}
                    href={link.href}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="flex items-center gap-4 group p-4 rounded-lg transition-all duration-300"
                    style={{ backgroundColor: `${link.color}10` }}
                    whileHover={{ 
                      x: isRTL ? -10 : 10,
                      backgroundColor: `${link.color}20`
                    }}
                    initial={{ opacity: 0, x: isRTL ? 50 : -50 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: index * 0.1 }}
                  >
                    <div 
                      className="w-12 h-12 rounded-full flex items-center justify-center transition-transform duration-300 group-hover:scale-110"
                      style={{ 
                        backgroundColor: `${link.color}20`,
                        color: link.color
                      }}
                    >
                      <link.icon className="w-6 h-6" />
                    </div>
                    <span 
                      className="text-lg font-medium transition-colors duration-300"
                      style={{ color: theme.text }}
                    >
                      {link.label}
                    </span>
                  </motion.a>
                ))}
              </div>
            </CustomCard>
          </motion.div>

          {/* Contact Form */}
          <motion.div
            initial={{ x: isRTL ? -100 : 100, opacity: 0 }}
            whileInView={{ x: 0, opacity: 1 }}
            transition={{ duration: 0.8 }}
          >
            <CustomCard style={{
              backgroundColor: isDark ? 'rgba(10, 25, 47, 0.8)' : 'rgba(255, 255, 255, 0.8)',
              borderColor: theme.primary
            }}>
              <form onSubmit={handleSubmit} className="space-y-6">
                <InputField
                  label={currentContent.formLabels.name}
                  id="name"
                  value={formData.name}
                  onChange={(e) => setFormData({...formData, name: e.target.value})}
                  theme={theme}
                />

                <InputField
                  label={currentContent.formLabels.email}
                  id="email"
                  type="email"
                  value={formData.email}
                  onChange={(e) => setFormData({...formData, email: e.target.value})}
                  theme={theme}
                />

                <InputField
                  label={currentContent.formLabels.message}
                  id="message"
                  value={formData.message}
                  onChange={(e) => setFormData({...formData, message: e.target.value})}
                  theme={theme}
                  rows={5}
                />

                <motion.button
                  type="submit"
                  disabled={isLoading}
                  whileHover={{ scale: 1.02 }}
                  whileTap={{ scale: 0.98 }}
                  className="w-full py-3 rounded-lg font-bold transition-all duration-300 disabled:opacity-50"
                  style={{
                    background: `linear-gradient(135deg, ${theme.primary}, ${theme.textSecondary})`,
                    color: isDark ? '#0a192f' : '#ffffff'
                  }}
                >
                  {isLoading ? (
                    <span className="flex items-center justify-center gap-2">
                      <motion.span
                        animate={{ rotate: 360 }}
                        transition={{ duration: 1, repeat: Infinity, ease: "linear" }}
                        className="w-5 h-5 border-2 border-current border-t-transparent rounded-full inline-block"
                      />
                      Processing...
                    </span>
                  ) : (
                    currentContent.formLabels.submit
                  )}
                </motion.button>
              </form>
            </CustomCard>
          </motion.div>
        </div>
      </div>
    </section>
  )
}